(() => {
  const root=document.querySelector('.hobbies-carousel');
  if(!root)return;
  const track=root.querySelector('.carousel-track');
  const originalSlides=[...root.querySelectorAll('.hobby-slide')];
  const firstClone=originalSlides[0].cloneNode(true);
  const lastClone=originalSlides.at(-1).cloneNode(true);
  firstClone.classList.add('is-clone');
  lastClone.classList.add('is-clone');
  firstClone.setAttribute('aria-hidden','true');
  lastClone.setAttribute('aria-hidden','true');
  track.prepend(lastClone);
  track.append(firstClone);
  const slides=[...root.querySelectorAll('.hobby-slide')];
  const reduce=window.matchMedia('(prefers-reduced-motion:reduce)');
  const viewer=document.createElement('div');
  viewer.className='image-viewer';
  viewer.hidden=true;
  viewer.setAttribute('role','dialog');
  viewer.setAttribute('aria-modal','true');
  viewer.setAttribute('aria-label','作品大图预览');
  viewer.innerHTML='<button class="image-viewer-close" type="button" aria-label="关闭大图">×</button><div class="image-viewer-inner"><img alt=""><p></p></div>';
  document.body.append(viewer);
  const viewerImage=viewer.querySelector('img');
  const viewerCaption=viewer.querySelector('p');
  let index=1,timer,startX=null,dragX=0,isAnimating=false,suppressClick=false,viewerOpen=false;
  const normalizedIndex=()=>((index-1)%originalSlides.length+originalSlides.length)%originalSlides.length;
  const render=(animate=true)=>{if(!animate)track.classList.add('no-transition');const slide=slides[0].getBoundingClientRect().width;const gap=parseFloat(getComputedStyle(track).columnGap)||0;const viewport=root.querySelector('.carousel-window').clientWidth;const x=viewport/2-(index*(slide+gap)+slide/2)+dragX;track.style.setProperty('--carousel-x',`${x}px`);originalSlides.forEach((item,i)=>item.setAttribute('aria-current',String(i===normalizedIndex())));if(!animate){track.offsetHeight;requestAnimationFrame(()=>track.classList.remove('no-transition'));}};
  const restart=()=>{clearInterval(timer);if(!reduce.matches&&!viewerOpen&&!document.hidden&&!root.matches(':hover'))timer=setInterval(()=>move(1),2600);};
  const move=(step)=>{if(isAnimating)return;index+=step;dragX=0;if(reduce.matches){if(index===0)index=originalSlides.length;if(index===originalSlides.length+1)index=1;render(false);restart();return;}isAnimating=true;render();restart();};
  const openViewer=(slide)=>{if(suppressClick)return;const image=slide.querySelector('img');viewerImage.src=image.currentSrc||image.src;viewerImage.alt=image.alt;viewerCaption.textContent=slide.querySelector('figcaption')?.textContent||image.alt;viewer.hidden=false;viewerOpen=true;document.body.classList.add('viewer-open');clearInterval(timer);viewer.querySelector('.image-viewer-close').focus();};
  const closeViewer=()=>{if(!viewerOpen)return;viewer.hidden=true;viewerOpen=false;viewerImage.removeAttribute('src');document.body.classList.remove('viewer-open');restart();};
  root.querySelector('.prev').addEventListener('click',()=>move(-1));
  root.querySelector('.next').addEventListener('click',()=>move(1));
  root.addEventListener('mouseenter',()=>clearInterval(timer));
  root.addEventListener('mouseleave',restart);
  slides.forEach((slide)=>{
    slide.tabIndex=slide.classList.contains('is-clone')?-1:0;
    slide.setAttribute('role','button');
    slide.setAttribute('aria-label',`${slide.querySelector('figcaption')?.textContent||'查看作品'}，点击查看完整图片`);
    slide.addEventListener('click',()=>openViewer(slide));
    slide.addEventListener('keydown',(event)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openViewer(slide);}});
    slide.addEventListener('pointermove',(event)=>{if(startX!==null)return;const rect=slide.getBoundingClientRect();slide.style.setProperty('--focus-x',`${((event.clientX-rect.left)/rect.width*100).toFixed(1)}%`);slide.style.setProperty('--focus-y',`${((event.clientY-rect.top)/rect.height*100).toFixed(1)}%`);});
    slide.addEventListener('pointerleave',()=>{slide.style.removeProperty('--focus-x');slide.style.removeProperty('--focus-y');});
  });
  track.addEventListener('transitionend',(event)=>{if(event.propertyName!=='transform')return;isAnimating=false;if(index===0){index=originalSlides.length;render(false);}else if(index===originalSlides.length+1){index=1;render(false);}});
  track.addEventListener('pointerdown',(event)=>{startX=event.clientX;suppressClick=false;track.setPointerCapture(event.pointerId);clearInterval(timer);});
  track.addEventListener('pointermove',(event)=>{if(startX===null)return;dragX=event.clientX-startX;if(Math.abs(dragX)>6)suppressClick=true;track.classList.add('no-transition');render();});
  track.addEventListener('pointerup',(event)=>{if(startX===null)return;const delta=event.clientX-startX;startX=null;track.classList.remove('no-transition');if(Math.abs(delta)>50){isAnimating=false;move(delta>0?-1:1);}else{dragX=0;render();restart();}setTimeout(()=>{suppressClick=false;},0);});
  viewer.querySelector('.image-viewer-close').addEventListener('click',closeViewer);
  viewer.addEventListener('click',(event)=>{if(event.target===viewer)closeViewer();});
  document.addEventListener('keydown',(event)=>{if(event.key==='Escape')closeViewer();});
  window.addEventListener('resize',render,{passive:true});
  document.addEventListener('visibilitychange',()=>document.hidden?clearInterval(timer):restart());
  requestAnimationFrame(()=>{render(false);restart();});
  const contact=document.querySelector('.contact-page');
  if(contact){const contactObserver=new IntersectionObserver((entries)=>{if(entries[0].isIntersecting){contact.classList.add('is-visible');contactObserver.disconnect();}},{threshold:.2});contactObserver.observe(contact);}
})();
